var ANIMALS=['猴','鸡','狗','猪','鼠','牛','虎','兔','龙','蛇','马','羊'];
var ELEMENTS=['木','木','火','火','土','土','金','金','水','水'];
function zodiac(year){ year=+year; if(!(year>=1)) return {error:'年份须为正'};
  var idx=((year%12)+12)%12;
  return {animal:ANIMALS[idx], element:ELEMENTS[(((year-4)%10)+10)%10], index:idx}; }
var EXPORTS={zodiac:zodiac, ANIMALS:ANIMALS, ELEMENTS:ELEMENTS};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ZodiacForgePure = EXPORTS; }
